<?php
// SARMAD Attendance - 1-Click Camera & UI Updater
header("Content-Type: text/html; charset=UTF-8");

$baseDir = __DIR__;
$results = [];

$files = [
    "assets/.htaccess" => "",
    "views/manager/employees/profile.php" => "",
    "views/manager/employees/index.php" => "",
    "assets/css/manager.css" => "",
    "assets/css/app.css" => ""
];

foreach ($files as $relPath => $b64) {
    $target = $baseDir . "/" . $relPath;
    $dir = dirname($target);
    if (!is_dir($dir)) {
        @mkdir($dir, 0755, true);
    }
    $data = base64_decode($b64);
    $ok = @file_put_contents($target, $data);
    if ($ok !== false) {
        $results[] = ["path" => $relPath, "status" => "success", "msg" => "با موفقیت به‌روزرسانی شد (" . strlen($data) . " بایت)"];
    } else {
        $results[] = ["path" => $relPath, "status" => "error", "msg" => "خطا در نوشتن فایل (دسترسی پوشه را بررسی کنید)"];
    }
}
?>
